scwin.btn_pimport_onclick = function() {debugger;
		//dataList1.setData([]);
		grid1.initGrid();
		if( !!$w.local.getItem('currGrid')){
			grid1.setGridStyle(WebSquare.xml.parse($w.local.getItem('currGrid'), true));
		}
		scwin.btn_sch_onclick();
	};
scwin.btn_pinit_onclick = function() {
		dataList1.setData([]);
		grid1.setGridStyle(WebSquare.xml.parse($w.local.getItem('initGrid'), true));
	};
scwin.grid1_onrightbuttonclick = function(row, col, e) {
		hiddenColGrp.hide();
		contextmenu.show('');
		contextmenu.setPosition(e.clientX, e.clientY);
	};
scwin.item1_onclick = function(e) {
		// 세로 틀고정.
		grid1.setFixedRow(grid1.getFocusedRowIndex());
	};
scwin.item2_onclick = function(e) {
		// 세로 틀고정 해제.
		grid1.setFixedRow(0);
	};
scwin.item3_onclick = function(e) {
		// 가로 틀고정.
		// 4. how to coding with the column index information when column moved ?????  
		grid1.setFixedColumn(grid1.getColumnOrder().indexOf(grid1.getFocusedColumnIndex()));
	};
scwin.item4_onclick = function(e) {
		// 가로 틀고정 해제.
		grid1.setFixedColumn(0);
	};
scwin.item5_onclick = function(e) { 
		// 컬럼 숨김.
		grid1.setColumnVisible( grid1.getFocusedColumnIndex() , false );
	};
scwin.item6_onclick = function(e) {
		// 전체 컬럼 숨김 해제.
		var i = 0;
		var rowNumVisible = grid1.options.rowNumVisible;
		var rowStatusVisible = grid1.options.rowStatusVisible;
		if( rowNumVisible == true && rowStatusVisible != true ){ i = 1; }
		else if( rowNumVisible != true && rowStatusVisible == true ){ i = 1; }
		else if( rowNumVisible == true && rowStatusVisible == true ){ i = 2; }

		var arr = grid1.hiddenList;
		for(var idx=i; idx< arr.length; idx++){
			if( arr[idx] == true) {
				var hiddenIdx = grid1.getColumnOrder()[idx-i];

				grid1.setColumnVisible(hiddenIdx , true);

				// remove object(WebSquare.util.dynamicCreate) in context menu list.
				var id = WebSquare.wUnit.getObjById( "item6_" + hiddenIdx );
				if(!!id){
					id.remove();
				}
			}
		}
	};
scwin.item6_onmouseover = function(e) {
		// 선택 컬럼 숨김 해제.
		var i = 0;
		var rowNumVisible = grid1.options.rowNumVisible;
		var rowStatusVisible = grid1.options.rowStatusVisible;
		if( rowNumVisible == true && rowStatusVisible != true ){ i = 1; }
		else if( rowNumVisible != true && rowStatusVisible == true ){ i = 1; }
		else if( rowNumVisible == true && rowStatusVisible == true ){ i = 2; }

		var arr = grid1.hiddenList;
		var cnt =0; 
		for(var idx=i; idx< arr.length; idx++){
			if( arr[idx] == true) {
				cnt++;
				var hiddenIdx = grid1.getColumnOrder()[idx-i];
				var headerIdArr = grid1.getHeaderIDArr(idx-i);
				var headerValue = grid1.getHeaderValue(headerIdArr[0]);

				var id = WebSquare.wUnit.getObjById( "item6_" + hiddenIdx );

				if(!id){
					// create the dynamic websquare object.
					WebSquare.util.dynamicCreate(
						"item6_" + hiddenIdx, /* string : 컴포넌트의 id */
				"textbox", /* string : 생성될 컴포넌트의 종류 */ {
					className: "item",
					style: "",
					label: headerValue
				}, /* object : 컴포넌트에 적용될 attribute 값*/
				hiddenColGrp //생성할 object의 부모
				);
				var id = WebSquare.wUnit.getObjById("item6_" + hiddenIdx);
				// create the dynamic event.
				id.bind("onclick", function(e) {
					var colIdx = parseInt(this.getID().split("_")[1]);
					grid1.setColumnVisible(colIdx, true);
					this.remove();
				});
				}
			}
		}
		if (cnt > 0) {
			hiddenColGrp.show('');
		}
};
scwin.item6_onmouseout = function(e) {
    hiddenColGrp.hide();
};
scwin.hiddenColGrp_onmouseover = function(e) {
    hiddenColGrp.show('');
};
scwin.hiddenColGrp_onmouseout = function(e) {
    hiddenColGrp.hide();
};
scwin.simulateWrapper = function(target, type, options) {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.setSimulate1 = function() {
    scwin.simulateWrapper('#grid1_column3', 'drag-n-drop', {
        dx: -100,
        dy: 0
    });
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById($p.id+'btn_pinit').children[0].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById($p.id+'btn_sch').children[0].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById($p.id+'btn_pexport').children[0].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById($p.id+'btn_pinit').children[0].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById($p.id+'btn_pimport').children[0].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_column11').next()[0].innerText == 'name7'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    // >= ie9  
    // Function : init 
    //------------------------------------
    // USE THE RESIZE HANDLER
    //------------------------------------
    document.onmousemove = function(e) {
        window.resizable = handler_horizontal.getUserData("resizable");
        if (resizable) {
            window.resizeGrp = WebSquare.wUnit.getObjById("resize_grp");
            // 0. WebSquare.wUnit.getJq("#resize_grp").offset().top ??? -> padding info.
            // if vertical scrollbar is visible in browser, you need to consider the scrollTop.  
            resize_grp.setSize(null, e.clientY - WebSquare.wUnit.getJq("#resize_grp").offset().top);
        }
    };
    document.onmouseup = function(e) {
        handler_horizontal.setUserData("resizable", false);
    };
    //------------------------------------
    document.onclick = function(e) {
        contextmenu.hide();
    };
    document.onselectstart = function(e) {
        // prevent the selection. 
        return false;
    };
    //------------------------------------
    // MAKE THE PERSONAL CUSTOM GRID
    //------------------------------------


	scwin.init();
	if (typeof scwin.unitTest === "function") {
		scwin.unitTest();
	}
};
